import{_ as s,a0 as o,w as i,s as p,I as n,x as e,a1 as r,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"瞭解團隊隱含價值觀和需求的指南 | LCTT x X-CMD","titleTemplate":false,"description":"瞭解團隊隱含價值觀和需求的指南 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"瞭解團隊隱含價值觀和需求的指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"瞭解團隊隱含價值觀和需求的指南 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210819 A guide to understanding your team-s implicit values and needs","title":"瞭解團隊隱含價值觀和需求的指南","tag":"202109","desc":""},"relativePath":"202109/20210819 A guide to understanding your team-s implicit values and needs.md","filePath":"[post].md"}'),u={name:"202109/20210819 A guide to understanding your team-s implicit values and needs.md"};function m(f,t,g,T,k,b){const l=o("Link");return i(),p("div",null,[t[23]||(t[23]=n("h1",{id:"瞭解團隊隱含價值觀和需求的指南",tabindex:"-1"},[e("瞭解團隊隱含價值觀和需求的指南 "),n("a",{class:"header-anchor",href:"#瞭解團隊隱含價值觀和需求的指南","aria-label":"Permalink to “瞭解團隊隱含價值觀和需求的指南”"},"​")],-1)),t[24]||(t[24]=n("blockquote",null,[n("p",null,"為了增強團隊動力，開放式領導可以研究指導成員行為和決策的隱性社會規範。")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/08/142831uj5zz2shqr1pybr2.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=e("文化在 ",-1)),r(l,{href:"https://theopenorganization.org/definition/"},{default:a(()=>[...t[0]||(t[0]=[e("開放式組織",-1)])]),_:1}),t[2]||(t[2]=e(" 很重要。但“文化”似乎是一個如此龐大而複雜的概念。我們該如何幫助開放式組織去理解它呢？",-1))]),n("p",null,[t[5]||(t[5]=e("一個解決方案可能來自於《",-1)),r(l,{href:"https://www.michelegelfand.com/rule-makers-rule-breakers"},{default:a(()=>[...t[3]||(t[3]=[e("Rule Makers, Rule Breakers",-1)])]),_:1}),t[6]||(t[6]=e("》的作者 ",-1)),r(l,{href:"https://www.michelegelfand.com/"},{default:a(()=>[...t[4]||(t[4]=[e("Michele J. Gelfand",-1)])]),_:1}),t[7]||(t[7]=e("：緊密和鬆散的文化以及指導我們生活的秘密信號。Gelfand 把所有的國家和文化分成簡單的兩類：一類是“緊密的”文化，另一類是“鬆散的”。然後，她解釋了兩者的特點和社會規範，提供了它們的相對優勢和劣勢。通過研究兩者，我們可以克服團隊、組織和國家之間的分歧和衝突。",-1))]),t[26]||(t[26]=d('<p>在這個分為兩篇的《Rule Makers, Rule Breakers》的點評中, 我將解釋 Gelfand 的論點，並討論它對在開放性組織中工作的人們有用的方式。</p><h3 id="瞭解你的社會規範" tabindex="-1">瞭解你的社會規範 <a class="header-anchor" href="#瞭解你的社會規範" aria-label="Permalink to “瞭解你的社會規範”">​</a></h3><p>Gelfand 認為，我們的行為很大程度上取決於我們是生活在“緊密的”還是“鬆散的”社區文化中，因為每一種文化都有不同於其他文化的社會規範。這些規範 ——— 以及強制執行的嚴格程度 ——— 將決定我們在社會中的行為。它們給了我們身份，它們幫助我們彼此協調。簡而言之，這些價值使社區團結在一起。</p><p>它們也會影響我們的世界觀，影響我們構造環境的方式，甚至影響我們大腦的處理過程。 Gelfand 寫道：“無數研究表明，社會規範對於將社區團結成合作、協調良好的團體，從而實現偉大成就至關重要。” 縱觀歷史，社區讓其公民參加看似最瘋狂的儀式，除了維持羣體凝聚力和合作外，別無其他原因。 這些儀式產生了更緊密的聯繫，使人們得以生存（特別是在狩獵、覓食和戰爭時期）。</p><p>社會規範包括我們所有人都會自動遵守的規則， Gelfand 稱之為一種 “規範性自動駕駛儀”。 這些是我們不需要思考就能做的事情————例如，在圖書館、電影院、電梯或飛機上保持安靜。 我們會自動的做這些事。 “從表面看，” Gelfand 説， “我們的社會規範通常看起來很奇怪。但在內心深處，我們認為這是理所當然的。” 她解釋到，社會規範可以被編入法規和法律（“遵守停車標誌”和“不要偷竊”）。還有一些基本上是不言而喻的（“不要盯着火車上的人看”或“打噴嚏時捂住嘴”）。當然，它們因環境而異。</p><p>挑戰在於大多數社會規範都是無形的，我們不知道這些社會規範在多大程度上控制着我們。在不知不覺中，我們常常只是跟隨周圍的人羣。這被稱為“羣體思維”，在這種思維中，人們會跟隨他們認同的羣體，即使這個羣體是錯誤的。他們不想站出來。</p><h3 id="組織-有松有緊" tabindex="-1">組織，有松有緊 <a class="header-anchor" href="#組織-有松有緊" aria-label="Permalink to “組織，有松有緊”">​</a></h3><p>Gelfand 將社會規範組織成不同的組別。她認為，一些規範具有“緊密”文化的特徵，而另一些規範則具有“鬆散”文化的特徵。為此， Gelfand 對來自五大洲 30 多個國家的約 7000 人進行了研究和抽樣，他們具有廣泛的職業、性別、年齡、宗教、教派，以及社會階層，以瞭解這些社區將自己定位在何處（以及他們的社會規範在官方和社區/社區總體上的執行力度）。 緊密和鬆散文化之間的差異在國家之間、國家內部（如美國及其各個地區）、組織內部、社會階層內部甚至家庭內部都有所不同。</p><p>因為組織有文化，它們也有自己的社會規範（畢竟，如果一個組織無法協調其成員並影響其行為，它將無法存在）。 因此，組織也可以反映和灌輸 Gelfand 所描述的“緊密”或“鬆散”的文化特徵。 並且如果我們有很強的能力識別這些差異，我們就能更成功地預測和解決衝突。然後，在對這些社會規範有了更高認識的情況下，我們可以將開放式組織原則付諸實踐。</p><p>Gelfand 這樣描述緊密和鬆散文化的區別：</p><blockquote><p>從廣義上講，鬆散的文化傾向於開放，但它們也更加無序。另一方面，緊密的文化有令人欣慰的秩序和可預測性，但它們的容忍度較低。這就是緊與松的權衡：一個領域的優勢與另一個領域的劣勢並存。</p></blockquote><p>她總結説，緊密的社會保持着嚴格的社會秩序、同步性和自律性；寬鬆的社會以高度寬容、富有創造力和對變化持開放態度而自豪。</p><p>雖然並非所有情況都是如此，但緊密和鬆散的文化通常會表現出一些權衡；每個人都有自己的長處和短處。參見下面的圖 1 。</p><p><img src="https://opensource.com/sites/default/files/images/open-org/rule-makers-breakers-1.png" alt=""></p><p>在這兩種環境中成功應用五項開放式組織原則的工作可能會有很大的不同。要取得成功，社區承諾至關重要，如果社會規範不同，承諾的理由也會不同。組織領導者必須知道社區的價值觀是什麼。只有這樣，這個人才能充分激勵他人。</p><p>在本點評的下一部分中，我將更徹底地解釋緊密文化和鬆散文化的特徵，以便領導者能夠更好地瞭解如何將開放式組織原則運用到團隊中。</p><hr>',17)),n("p",null,[t[9]||(t[9]=e("via: ",-1)),r(l,{href:"https://opensource.com/open-organization/21/8/leadership-cultural-social-norms"},{default:a(()=>[...t[8]||(t[8]=[e("https://opensource.com/open-organization/21/8/leadership-cultural-social-norms",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("作者：",-1)),r(l,{href:"https://opensource.com/users/ron-mcfarland"},{default:a(()=>[...t[10]||(t[10]=[e("Ron McFarland",-1)])]),_:1}),t[15]||(t[15]=e(" 選題：",-1)),r(l,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 譯者：",-1)),r(l,{href:"https://github.com/zz-air"},{default:a(()=>[...t[12]||(t[12]=[e("zz-air",-1)])]),_:1}),t[17]||(t[17]=e(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原創編譯，",-1)),r(l,{href:"https://linux.cn/"},{default:a(()=>[...t[19]||(t[19]=[e("Linux中國",-1)])]),_:1}),t[22]||(t[22]=e(" 榮譽推出",-1))])])}const w=s(u,[["render",m]]);export{G as __pageData,w as default};
